function V(id, sv, en, base, al) { VARIANTS.push([id, sv, en, base, al]); }
function F(id, sv, en, cat, d, pc, v, al, pop) {
  const n = {};
  NUTRIENT_KEYS.forEach((k, i) => { if (v[i]) n[k] = v[i]; });
  FOOD_DB.push({ id, sv, en, cat, d: d || 0, pc: pc || {}, n, al: al || [], pop: !!pop });
}
