/* Family names (e.g. "Spaghetti (pasta)") share the nutrients of their base food */
(function () {
  const idx = {}; FOOD_DB.forEach(f => { idx[f.id] = f; });
  VARIANTS.forEach(([id, sv, en, base, al]) => {
    const f = idx[base]; if (!f) return;
    FOOD_DB.push({ id, sv, en, cat: f.cat, d: f.d, pc: f.pc, n: f.n, al: al || [], pop: true, base });
  });
})();
